window.__saqPaperQuestions("2021-1-st-george",[{"number":1,"title":"","stemText":"A 3yo boy is brought to the ED by his parents with concern for foreign body ingestion.\nAn XR is performed and shown below :\nCourtesy of BMJ Vol 97 Iss 8","parts":[{"id":"a","label":"Part A","prompt":"What is the diagnosis? Justify your answer. (1 mark)"},{"id":"b","label":"Part B","prompt":"State (2) specific management options for this. (2 marks) 1. 2."},{"id":"c","label":"Part C","prompt":"With respect to paediatric foreign body (FB) ingestion in general, list (4) high risk features pertaining to the FB and (4) relating to the patient. (8 marks) Foreign body Patient"}],"propPages":["asset:img7975778842a2fd9510"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Oesophageal button battery – circle on AP, double ring or halo sign </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em><strong>Immediate referral to ENT/gastroenterology for expeditious removal in OT </strong></em></div><div class=\"answer-line\"><em>Trial 10mL PO honey q10 minutes if child able to swallow and no signs of perf/bleeding </em></div><div class=\"answer-line\"><em>(should not delay removal) </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>Pre-existing GIT abnormalities eg </em></td></tr><tr><td><em>Large objects &gt;6cm long and/or &gt;2cm wide </em></td><td><em>oesophageal atresia </em></td></tr><tr><td><em>Superabsorbent polymers  </em></td><td><em>Oesophageal strictures </em></td></tr><tr><td><em>Toxic objects eg lead, iron tablets </em></td><td><em>Eosinophilic oesophagitis </em></td></tr><tr><td><em>Multicomponent objects </em></td><td><em>Neuromuscular disease </em></td></tr><tr><td><em>Sharp object in oesophagus </em></td><td><em>Pre-existing oesophageal varices </em></td></tr><tr><td colspan=\"2\"><em>Unsafe swallow </em></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 56yo woman presents with chest pain of three hours duration that radiated into her back.\nFollowing 5mg IV morphine, her pain is now “very mild”.","parts":[{"id":"a","label":"Part A","prompt":"In addition to aortic dissection, list (2) pathologic diagnoses which are encapsulated by the term ‘Acute Aortic Syndrome’. (2 marks) 1. 2."},{"id":"b","label":"Part B","prompt":"List and justify (5) investigations you would utilise in the workup of acute aortic syndrome (10 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Intramural haematoma </em></div><div class=\"answer-line\"><em>Penetrating aortic ulcer </em></div><div class=\"answer-line\"><em>Traumatic disruption of the aorta </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em><strong>Look for complications</strong></em><em> ie coronary artery involvement (usually RCA) 7%, secondary </em></td></tr><tr><td colspan=\"2\"><em>myocardial ischaemia 10-40%, electrical alternans (tamponade) </em></td></tr><tr><td colspan=\"2\"><em><strong>May detect alternate diagnoses eg PE/ACS unrelated to AAS </strong></em></td></tr><tr><td colspan=\"2\"><em>Cheap/noninvasive/repeatable (weak answer, no marks) </em></td></tr><tr><td><strong>CXR </strong></td><td><em><strong>Poor Sn and Sp but may show radiologic signs of AD</strong></em><em> ie. Widened mediastinum, </em></td></tr><tr><td colspan=\"2\"><em>abnormal aortic contour, double calcium sign, pleural effusion, apical cap, </em></td></tr><tr><td colspan=\"2\"><em>deviated NGT </em></td></tr><tr><td colspan=\"2\"><em>May suggest alternate dx eg PTX/pneumonia </em></td></tr><tr><td><strong>D-dimer </strong></td><td><em>Good evidence that in combination with low clinical risk score can r/o AAS </em></td></tr><tr><td colspan=\"2\"><em>with &gt;99.5% NPV </em></td></tr><tr><td><strong>TTE </strong></td><td><em>Rapid bedside assessment of unstable patient  </em></td></tr><tr><td colspan=\"2\"><em>May demonstrate complications eg AR, tamponade, RWMA </em></td></tr><tr><td colspan=\"2\"><em>May show AAA, flap </em></td></tr><tr><td><strong>TOE </strong></td><td><em>High Sn and Sp – similar to CTA </em></td></tr><tr><td colspan=\"2\"><em>Functional assessment of AV and LV </em></td></tr><tr><td colspan=\"2\"><em>Able to detect complications ie. pericardial effusion </em></td></tr><tr><td colspan=\"2\"><em>Can be performed at beside in unstable patient </em></td></tr><tr><td><strong>CTA </strong></td><td><em><strong>Preferred study in stable patient with high Sn (97%) and Sp (97%) </strong></em></td></tr><tr><td colspan=\"2\"><em>Can identify extent of dissection (Type A vs Type B) and branch artery involvement </em></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 55yo male presents to ED with 5 days of progressive pain and discolouration to his right foot. Vital signs are: HR 90, BP 150/90, SaO2 98% RA, RR 16, temp 38°C, BSL 24. Clinical images are shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (3) abnormal physical findings along with a unifying diagnosis. (4 marks) 1. 2. 3. Unifying diagnosis :"},{"id":"b","label":"Part B","prompt":"List (4) pathophysiological processes that may have contributed to the development of this problem. (4 marks) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"Outline your management of this patient. (4 marks) 1. 2. 3. 4."}],"propPages":["asset:imgcd8d41d5e990728216","asset:imgfd42f6c2912239ca4a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em><strong>Necrotic ulcer</strong></em><em> / </em><em><strong>gangrene</strong></em><em> around base of hallux </em></div><div class=\"answer-line\"><em>Pallor to ball of foot </em></div><div class=\"answer-line\"><em>Surrounding flare of cellulitis </em></div><div class=\"answer-line\"><em>Venous eczema over medial malleolus </em></div><div class=\"answer-line\"><strong>Unifying diagnosis : </strong></div><div class=\"answer-line\"><em><strong>Severe diabetic foot infection</strong></em><em> with established gangrene of big toe </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em><strong>Diabetic neuropathy</strong></em><em> / unrecognised trauma </em></div><div class=\"answer-line\"><em>Arterial insufficiency  </em></div><div class=\"answer-line\"><em>Venous insufficiency </em></div><div class=\"answer-line\"><em>Bacterial superinfection / osteomyelitis </em></div><div class=\"answer-line\"><em>Poor glycaemic control </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em><strong>IV antibiotics</strong></em><em>: e.g. tazocin 4.5g TDS IV </em></div><div class=\"answer-line\"><em><strong>Urgent vascular</strong></em><em> </em><em><strong>surgery consultation</strong></em><em> – will likely need amputation </em></div><div class=\"answer-line\"><em>Manage hyperglycaemia – insulin infusion or sliding scale </em></div><div class=\"answer-line\"><em>Pain relief </em></div><div class=\"answer-line\"><em>(X-ray to check for osteomyelitis) </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"You are asked by the senior ED nurse to review a 75yo female, who has developed dyspnoea and neck swelling after failed insertion of a CVC by one of the junior ED registrars. A CT angiogram of the neck has been performed :","parts":[{"id":"a","label":"Part A","prompt":"List (2) significant abnormalities on the CT scan (2 marks). 1. 2."},{"id":"b","label":"Part B","prompt":"List (3) significant complications that may have resulted from this procedure. (3 marks) 1. 2. 3. You discover that the patient has been in the department for 4 hours and has been treated with empirical antibiotics for presumed urosepsis. She has received 3.5L of IV crystalloid for management of persistent hypotension. She has a background of AF, for which she takes warfarin... On returning from the CT scanner, the patient is found be distressed and unable to lie flat. She has developed new onset of stridor. There is no rash, wheeze or angio-oedema.\nHer vital signs are:\n\nHR\n100\n\nBP\n85/50\n\nSaO2 95% RA\n\nRR\n\nTemp 39°C"},{"id":"c","label":"Part C","prompt":"Briefly state your immediate management priorities for this patient. (4 marks) 1. 2. 3. 4. The senior nurse expresses some concerns regarding the registrar’s management of this case and asks you to feed back to them."},{"id":"d","label":"Part D","prompt":"List (4) issues that you would discuss with the ED registrar (4 marks) 1. 2. 3. 4. The patient’s family arrive and are requesting to speak to you for a clinical update."},{"id":"e","label":"Part E","prompt":"List (5) components of your approach to communicating with the family. (5 marks) 1. 2. 3. 4. 5."}],"propPages":["asset:imgd78a74e4bbd95ab3c1"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Large </em><em><strong>contrast blush from the right carotid artery</strong></em><em> suggests carotid puncture</em><em> </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em><strong>Expanding neck haematoma</strong></em><em> causing airway compromise </em></div><div class=\"answer-line\"><em><strong>Carotid artery injury</strong></em><em> leading to haemorrhage / dissection / stroke </em></div><div class=\"answer-line\"><em><strong>Pneumothorax</strong></em><em> also a possibility (patient is dyspnoeic) </em></div><div class=\"answer-line\"><em>Air embolism also possible but nothing in scenario to indicate this has occurred </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em><strong>Urgent vascular surgery consultation</strong></em><em> – consider carotid artery repair at OT or IR </em></div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\"><em><strong>Reverse warfarin</strong></em><em> – prothrombinex, FFP, vit K </em></div><div class=\"answer-line\"><strong>4. </strong></div><div class=\"answer-line\"><em>Careful BP management, may require pressors but avoid driving MAP too high! </em></div><div class=\"answer-line\"><em><strong>NOT </strong></em><em>anaphylaxis management given the scenario </em></div><div class=\"answer-line\"><em>CXR / lung USS to assess for pneumothorax </em></div><div class=\"answer-line\"><em>(Will need ICU admission for monitoring and sepsis Mx after OT/IR) </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>CVC insertion technique – Was ultrasound used? Was the carotid artery dilated?? </em></td></tr><tr><td><strong>2. </strong></td><td><em>Insertion of CVC in anticoagulated patient </em></td></tr><tr><td><strong>3. </strong></td><td><em>Excessive fluid resuscitation in elderly patient </em></td></tr><tr><td><strong>4. </strong></td><td><em>Failure to escalate – patient has been in ED for 4 hours </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><em>Find a quiet room to speak privately, leave phone/pager behind </em></div><div class=\"answer-line\"><em>Take a colleague with you to support family (e.g. social worker, nurse) </em></div><div class=\"answer-line\"><em>Outline medical issues and sequence of events </em></div><div class=\"answer-line\"><em>Empathetic communication, avoid jargon  </em></div><div class=\"answer-line\"><em><strong>Full open disclosure</strong></em><em> regarding incident – explain what has happened </em></div><div class=\"answer-line\"><em>Stick to known facts, avoid speculation or blame </em></div><div class=\"answer-line\"><em>Express regret regarding adverse event without admitting liability </em></div><div class=\"answer-line\"><em>Promise to </em><em><strong>investigate</strong></em><em> further  </em></div><div class=\"answer-line\"><em>Make plan to feed back further to family once all the facts known </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 6yo girl is brought to ED by her mother with a complication related to a recent ear piercing. She has a stud earring deeply embedded in her ear lobe, which is swollen, red and very tender to touch. The skin of the ear lobe has overgrown and engulfed the piercing on both sides, making simple manual removal of the piercing impossible. She is highly distressed and complains of severe pain. She will not let you anywhere near the ear.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table below\n• utlining\n(2) suitable methods\n• f\nproviding analgesia/anaesthesia during foreign body removal, including doses and routes of administration. List (2)"},{"id":"b","label":"Part B","prompt":"Provide a stepwise approach on how you would remove the foreign body. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"What else would you do prior to discharging the patient? (3 marks) 1. 2. 3."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td><em>Ketamine  </em></td><td><em>Excellent </em></td><td><em>Resource-intensive, need resus </em></td></tr><tr><td><em>1-1.5mg/kg IV or </em></td><td><em>analgesia/sedation </em></td><td><em>bay, staff, monitoring, etc </em></td></tr><tr><td><em>3-4mg/kg IM </em></td><td><em>Patient more likely to </em></td><td></td></tr><tr><td><em>remain still for procedure </em></td><td><em>Potential risks: N+V, </em></td><td></td></tr><tr><td><em>Procedure will be better </em></td><td><em>laryngospasm, apnoea (rare) </em></td><td></td></tr><tr><td><em>tolerated by patient </em></td><td></td><td></td></tr><tr><td><strong>2. </strong></td><td><em>Nitrous oxide </em></td><td><em>Readily available </em> <em>Patient needs to be cooperative </em></td></tr><tr><td><em>50:50 from </em></td><td><em>to use Entonox </em></td><td></td></tr><tr><td><em>Entonox cylinder </em></td><td><em>May be sufficient for </em></td><td></td></tr><tr><td><em>or 30-70% via </em></td><td><em>procedure </em></td><td><em>Not as effective as ketamine </em></td></tr><tr><td><em>blender </em></td><td></td><td></td></tr><tr><td><em>+/- IN fentanyl </em></td><td><em>Avoid risk of anaesthetic </em></td><td><em>Patient may not be able to keep </em></td></tr><tr><td><em>1.5mcg/kg </em></td><td><em>still </em></td><td></td></tr><tr><td><em>Other options probably not suitable for a paediatric case: </em></td><td></td><td></td></tr><tr><td><em>Ear block with LA, direct LA infiltration </em></td><td></td><td></td></tr><tr><td><em>EMLA to ear lobe probably not sufficient anaesthesia (but reasonable adjunct) </em></td><td></td><td></td></tr><tr><td><em>Marking scheme: 0.5 marks for each item</em></td><td></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Palpate earring under the skin </em></div><div class=\"answer-line\"><em>Make small incisions as required with scalpel to expose both sides of the earring </em></div><div class=\"answer-line\"><em>Remove the fastener and push earring through to remove </em></div><div class=\"answer-line\"><em>Express any blood or pus </em></div><div class=\"answer-line\"><em>Irrigate thoroughly with normal saline </em></div><div class=\"answer-line\"><em>Apply a simple dressing </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Observe until sedation wears off </em></div><div class=\"answer-line\"><em>Update tetanus status as required; consider need for antibiotics  </em></div><div class=\"answer-line\"><em>Top up analgesia </em></div><div class=\"answer-line\"><em>Provide discharge advice – i.e. return precautions, follow-up with GP </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 75yo female presents to ED with right loin pain and rigors. She has a past history of T2DM and hypertension and takes regular metformin, gliclazide, ramipril and amlodipine.\nHer vital signs are:\n\nHR\n102\n\nBP\n90/60\n\nRR\n\nSaO2 95% RA\n\nTemp 39°C\nHer CT KUB is shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (4) abnormalities visible on this CT scan (4 marks) and provide a unifying diagnosis (1 mark) 1. 2. 3. 4. Unifying diagnosis :"},{"id":"b","label":"Part B","prompt":"Outline your management priorities for this patient. (4 marks) 1. 2. 3. 4. The patient develops acute severe kidney injury with oliguria."},{"id":"c","label":"Part C","prompt":"List (3) complications you would monitor for in this patient (3 marks). 1. 2. 3."}],"propPages":["asset:img539f87b575f211250e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>Extensive peri-renal stranding R&gt;L </em></td></tr><tr><td><strong>2. </strong></td><td><em>Stone in right renal pelvis </em></td></tr><tr><td><strong>3. </strong></td><td><em>Proximal right hydroureter </em></td></tr><tr><td><strong>4. </strong></td><td><em>Air in right kidney </em></td></tr><tr><td colspan=\"2\"><strong>Unifying diagnosis</strong> :</td></tr><tr><td colspan=\"2\"><em>Diagnosis: Emphysematous pyelonephritis. May accept “infected, obstructed stone” if </em></td></tr><tr><td colspan=\"2\"><em>presence of gas-forming organisms noted somewhere. </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em><strong>Urgent urology review</strong></em><em> for surgical decompression of kidney with either </em></td></tr><tr><td colspan=\"2\"><em>nephrostomy or JJ stent </em></td></tr><tr><td><strong>2. </strong></td><td><em><strong>Broad spectrum antibiotic cover</strong></em><em>: IV amoxicillin/ampicillin 2g plus gentamicin 5-</em></td></tr><tr><td colspan=\"2\"><em>7mg/kg OR Tazocin 4.5g acceptable </em></td></tr><tr><td><strong>3. </strong></td><td><em><strong>Haemodynamic resuscitation </strong></em><em>: judicious crystalloid bolus (10mL/kg) reassess and </em></td></tr><tr><td colspan=\"2\"><em>repeat aiming for MAP &gt;65mmHg, early use of vasopressors if persistent/worsening </em></td></tr><tr><td colspan=\"2\"><em>hypotension  </em></td></tr><tr><td><strong>4. </strong></td><td><em><strong>Analgesia</strong></em><em> – safe agents, e.g. IV fentanyl 25-50mcg, paracetamol. NSAIDs not ideal.  </em></td></tr><tr><td colspan=\"2\"><em>(Will need HDU/ICU-level care due to risks of progressive septic shock, likely needing </em></td></tr><tr><td colspan=\"2\"><em>vasopressors) </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Metformin-related </em><em><strong>lactic acidosis</strong></em><em> </em></div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\"><em><strong>Hypoglycaemia</strong></em><em> due to renal accumulation of gliclazide </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 74yo man is brought to ED by ambulance after a collapse at home.\n\nVital signs are:\n\nHR\n\nBP\n90/50\n\nSaO2 95% RA\n\nRR\n\nTemp 36°C\n\nBSL\n7.0 His ECG is shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (5) pertinent features on the ECG (5 marks) and give your overall interpretation of the ECG changes (1 mark) 1. 2. 3. 4. 5. Interpretation : Prior to initiating any medical management, the patient indicates that he wishes to self- discharge against medical advice."},{"id":"b","label":"Part B","prompt":"What would you say to him regarding this decision? (1 mark)"},{"id":"c","label":"Part C","prompt":"List (5) elements of capacity/competence that you would assess in this man regarding his decision to self-discharge. (5 marks) 1. 2. 3. 4. 5."}],"propPages":["asset:img9ee39fde57dabfcca0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Sinus rhythm ~120bpm with associated </em><em><strong>high-grade AV block</strong></em><em> (presumably the reason for </em></div><div class=\"answer-line\"><em>PPM) </em></div><div class=\"answer-line\"><em><strong>Pacing spikes</strong></em><em> follow each native P wave </em></div><div class=\"answer-line\"><em>Approximately half the pacing spikes are followed by a paced QRS </em></div><div class=\"answer-line\"><em><strong>Approximately half the pacing spikes are not followed by a paced QRS </strong></em></div><div class=\"answer-line\"><em>Resultant ventricular rate is ~60. No obvious ischaemic changes. </em><em> </em></div><div class=\"answer-line\"><strong>Interpretation :</strong><em> </em></div><div class=\"answer-line\"><em>Paced rhythm with intermittent failure to capture</em><em> </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>High risk of cardiac arrest, may die if he self-discharges home  </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Ability to </em><em><strong>understand</strong></em><em> relevant information </em></div><div class=\"answer-line\"><em>Ability to </em><em><strong>retain</strong></em><em> information relevant to the decision </em></div><div class=\"answer-line\"><em>Ability to appreciate the situation and its </em><em><strong>consequences</strong></em><em> </em></div><div class=\"answer-line\"><em>Ability to </em><em><strong>weigh up</strong></em><em> the information in a rational fashion</em><em> </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 5yo girl is brought into ED by her parents. She has been unwell for 3 days with lethargy, restlessness and poor oral intake. The patient and other members of the family had a bout\n• f gastroenteritis, presumed food poisoning, about 2 weeks ago.\nOn examination she appears pale with vitals as follows :\n\nHR\n130\n\nBP\n125/80\n\nRR\n\nSats\n99% RA\n\nTemp\n37°C A VBG is taken :\n\npH\n7.35\n\npCO2\n\npO2\n\nHb\n\nK\n4.7\n\nCr\nLact 1.5","parts":[{"id":"a","label":"Part A","prompt":"What is the MOST CONCERNING diagnosis? Justify your answer. (2 marks) Diagnosis Justification"},{"id":"b","label":"Part B","prompt":"List (4) possible pathogens for this illness. (2 marks - 1⁄2 mark each) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"Complete the table below stating expected findings for this condition. (6 marks) FBC Blood film LDH Haptoglobin LFT Direct antiglobulin test"},{"id":"d","label":"Part D","prompt":"What are your clinical concerns? State your management strategy for each (4 marks) Clinical Concern Strategy"},{"id":"e","label":"Part E","prompt":"List (4) possible complications from this condition. (4 marks) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Haemolytic-uraemic syndrome</em><strong> </strong></div><div class=\"answer-line\"><strong>Justification </strong></div><div class=\"answer-line\"><em>Profound anaemia, AKI with HTN, preceding gastroenteritis </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Salmonella typhi </em></div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\"><em>Shigella </em></div><div class=\"answer-line\"><strong>4. </strong></div><div class=\"answer-line\"><em>Campylobacter </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Normocytic anaemia, </em><em><strong>thrombocytopaenia</strong></em><em> </em></div><div class=\"answer-line\"><strong>Blood film </strong></div><div class=\"answer-line\"><em>Schistocytes  </em></div><div class=\"answer-line\"><strong>LDH </strong></div><div class=\"answer-line\"><em>Elevated from haemolysis </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Profound anaemia</td><td><em>10mL/kg packed RBC </em></td></tr><tr><td>Hypertension</td><td><em>PO nifedipine or PO/IV labetalol </em></td></tr><tr><td>AKI</td><td><em>Careful attention to fluid and electrolyte balance, </em></td></tr><tr><td><em>anticipate and treat hyper K, may require dialysis </em></td><td></td></tr><tr><td>Thrombocytopaenia</td><td><em>Platelet transfusion only if bleeding as may worsen </em></td></tr><tr><td><em>situation </em></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><em>CNS : stroke/seizure/coma/cortical blindness </em></div><div class=\"answer-line\"><em>Bowel : haemorrhagic colitis, necrosis, perforation, intussusception </em></div><div class=\"answer-line\"><em>Myocarditis </em></div><div class=\"answer-line\"><em>Pancreatitis </em></div><div class=\"answer-line\"><em>Glucose intolerance </em></div><div class=\"answer-line\"><em>Cholestatic jaundice </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You have been asked to write a management plan for a 35yo male who has become a frequent presenter to your ED with back pain. There have been several incidents of aggressive behaviour involving this man, requiring his removal by security. The ED nurse manager suspects that he is seeking opiates.","parts":[{"id":"a","label":"Part A","prompt":"List (6) elements of the patient’s history that would be suspicious for drug-seeking behaviour. (6 marks) 1. 2. 3. 4. 5. 6."},{"id":"b","label":"Part B","prompt":"State (6) pieces of information that you would include in this patient’s ED management plan (6 marks) 1. 2. 3. 4. 5. 6."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Frequent presentations to multiple EDs requesting pain relief </em></div><div class=\"answer-line\"><em>ED visits focused on obtaining pain relief rather than investigating cause of pain </em></div><div class=\"answer-line\"><em><strong>Multiple opiate prescriptions from different providers</strong></em><em>, flagged by doctor-shopping </em></div><div class=\"answer-line\"><em>hotline </em></div><div class=\"answer-line\"><em>Reluctant to provide full history or engage with medical assessment </em></div><div class=\"answer-line\"><em>Anger or irritability when questioned about reasons for ED presentation </em></div><div class=\"answer-line\"><em>Frequently self-discharges after receiving opiates </em></div><div class=\"answer-line\"><em>Asking for specific drugs by name or in specific doses </em></div><div class=\"answer-line\"><em>Claims that paracetamol or NSAIDs do not work </em></div><div class=\"answer-line\"><em>History of IVDU / treatment for opiate addiction </em></div><div class=\"answer-line\"><em>History of absconding with IV cannula in situ </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>History of previous presentations with back pain and </em><em><strong>current working diagnosis</strong></em><em> </em></div><div class=\"answer-line\"><em>History of previous episodes of aggression and how these were resolved </em></div><div class=\"answer-line\"><em>Past medical history including any relevant medical or surgical diagnoses </em></div><div class=\"answer-line\"><em>Past mental health history including drug &amp; alcohol use; forensic history </em></div><div class=\"answer-line\"><em>Medication history and allergies </em></div><div class=\"answer-line\"><em><strong>Plan for medical assessment</strong></em><em> – early review by senior doctor </em></div><div class=\"answer-line\"><em><strong>Plan for pain relief</strong></em><em> – e.g. avoid opiate use during initial assessment </em></div><div class=\"answer-line\"><em><strong>Plan for dealing with aggression</strong></em><em> – zero tolerance to aggressive behaviour </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 75yo female is brought to ED by her daughter after an episode of syncope at home.\nShe has a background history of hypertension, atrial fibrillation and depression. On arrival to ED, her vital signs are as follows:\n\nHR\n\nBP\n80/50\n\nRR\n\nSaO2\n98% RA\n\nTemp\n36.5°C\n\nGCS\nHer first ECG on arrival to ED is shown below :","parts":[{"id":"a","label":"Part A","prompt":"List three (3) relevant findings on this ECG. (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"List (3) potential causes of this ECG appearance. (3 marks) 1. 2. 3. Whilst in ED, she has several brief episodes of presyncope with associated palpitations. A second ECG is captured during one of these episodes :"},{"id":"c","label":"Part C","prompt":"What does the second ECG show? (1 mark) The patient develops progressive bradycardia and hypotension. She now appears pale and\ndiaphoretic with HR 30 bpm, BP 60/40, CRT 4s. The monitor shows sinus bradycardia. She\ncontinues to have intermittent paroxysms of rapid heart rate during which she transiently loses consciousness."},{"id":"d","label":"Part D","prompt":"Outline your next steps in management. (5 marks) 1. 2. 3. 4. 5."}],"propPages":["asset:img445736bb330b607e46","asset:imgd7084b198f6a0fffce"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Sinus rhythm 60bpm </em></div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\"><em>Prolonged PR interval ~280ms </em></div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\"><em><strong>Long QT interval</strong></em><em> ~600ms </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Drug toxicity, especially </em><em><strong>amiodarone</strong></em><em>, </em><em><strong>sotalol</strong></em><em>; antipsychotics, macrolides, </em></div><div class=\"answer-line\"><em>antimalarials </em></div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\"><em>Electrolyte abnormalities: </em><em><strong>hypokalaemia</strong></em><em>, hypomagnesaemia (appearance not </em></div><div class=\"answer-line\"><em>typical of hypocalcaemia) </em></div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\"><em>Others: hypothermia, myocardial ischaemia, congenital LQTS </em></div><div class=\"answer-line\"><em><strong>MUST include amiodarone or sotalol given the clinical vignette </strong></em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Polymorphic VT – most likely </em><em><strong>Torsades de Points</strong></em><em> given the long QT </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><em><strong>Fluid bolus</strong></em><em> – 10-20ml/kg of crystalloid </em></div><div class=\"answer-line\"><em><strong>Trial of atropine</strong></em><em> 0.6-1.2mg is reasonable </em></div><div class=\"answer-line\"><em><strong>Commence adrenaline infusion</strong></em><em> – 6mg/100ml at 2-10ml/hr (isoprenaline not ideal as it </em></div><div class=\"answer-line\"><em>may further drop the BP) </em></div><div class=\"answer-line\"><em><strong>Correct electrolytes</strong></em><em> – K, Mg, Ca - will need magnesium load 2-4g to suppress TdP but </em></div><div class=\"answer-line\"><em>give slowly as may further drop BP </em></div><div class=\"answer-line\"><em>Consider </em><em><strong>overdrive pacing</strong></em><em> at 100-120 bpm for suppression of TdP </em></div><div class=\"answer-line\"><em>(Admit to ICU for monitoring </em></div><div class=\"answer-line\"><em>Gather further info / collateral Hx - ?overdose of cardiac medications) </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 64yo female is brought to ED by ambulance with an altered conscious state after a seizure. She was initially unresponsive on scene but now responds to painful stimuli. Her ABG is provided below :\n\npH\n7.32\n\nNa\n112\n\nPCO2 31\n\nK\n4.1\n\nPO2\n110 (FiO2 21%)\n\nCl\n\nBE\n- 6.0 Gluc 7.0\n\nHCO3 17\n\nUrea 3.0\n\nLactate 4.7","parts":[{"id":"a","label":"Part A","prompt":"Comment on (3) relevant abnormalities. (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"Complete the table below providing : (3) categories of hyponatraemia relevant to this patient and (2) plausible differential diagnoses for each category (= 6 marks total) Category of Differential Diagnoses Hyponatraemia 1. A B 2. A B 3. A B"},{"id":"c","label":"Part C","prompt":"Outline your immediate actions. (3 marks) 1. 2. 3."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Critical hyponatraemia of 112 = likely cause for seizure </em></div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\"><em>Low serum osmolality = (2x112+7+3 = 234) c/w hypotonic hyponatraemia </em></div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\"><em>Mild HAGMA (lactic) with resp compensation – c/w seizure </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Differential Diagnoses </strong></td><td></td></tr><tr><td><strong>Hyponatraemia </strong></td><td></td></tr><tr><td><strong>1. </strong></td><td><em>Hypovolaemic </em> <strong>1A. </strong><em>Renal losses: diuretics, nephropathy.  </em></td></tr><tr><td><em>Addison’s NOT likely given K and glucose </em></td><td></td></tr><tr><td><strong>1B. </strong><em>Extra-renal losses: D+V, sweating (heat </em></td><td></td></tr><tr><td><em>exhaustion) </em></td><td></td></tr><tr><td><strong>2. </strong></td><td><em>Euvolaemic </em> <strong>2A. </strong><em>SIADH: drugs (MDMA), meds (SSRIs), brain/lung </em></td></tr><tr><td><em>pathology </em></td><td></td></tr><tr><td><strong>2B. </strong><em>Water intoxication, e.g. psychogenic polydipsia </em></td><td></td></tr><tr><td><strong>3. </strong></td><td><em>Hypervolaemic </em> <strong>3A. </strong><em>CCF </em></td></tr><tr><td><strong>3B. </strong><em>Liver failure/nephrotic </em></td><td></td></tr><tr><td><em>syndrome/hypoalbuminaemia </em></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Support airway and breathing: provide O2, airway positioning/adjuncts as required </em></div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\"><em><strong>Terminate seizure : hypertonic saline</strong></em><em>: 100ml bolus of 3%; may be repeated x 2 (aim </em></div><div class=\"answer-line\"><em>to correct Na by &lt;6mmol/L in 6hrs) </em></div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\"><em>Consider IV midazolam bolus and prepare for intubation if no response to HS </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"You are called urgently to the resuscitation room to assist with the post-intubation\nmanagement of a 50kg, 23yo female with life-threatening asthma. She was intubated by the\nED registrar after failing to respond to medical therapy. The ventilator is alarming continuously with a high-pressure alarm. The registrar has dialled up a tidal volume of 550ml, but only 200ml is being delivered. Propofol and fentanyl infusion is being administered for post-intubation sedation. The patient’s vital signs are:\n\nHR\n130\n\nBP\n78/40\n\nRR (vent)\n15/min\n\nSaO2\n93% on FiO2 100%","parts":[{"id":"a","label":"Part A","prompt":"State your immediate actions. (9 marks) 1. 2. 3. 4. 5. 6. 7. 8. 9."},{"id":"b","label":"Part B","prompt":"Complete the table below with ventilator settings appropriate for this clinical scenario (5 marks) Tidal volume\n\nRR\nPEEP"},{"id":"d","label":"Part D","prompt":"Outline (4) other strategies you would employ to optimise ventilation and oxygenation for this patient. (4 marks) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["E ratio Peak airway pressure Plateau pressure"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em><strong>Take patient off ventilator and manually ventilate</strong></em><em> with 100% FiO2, assess lung </em></td></tr><tr><td colspan=\"2\"><em>compliance </em></td></tr><tr><td><strong>2. </strong></td><td><em><strong>Check for ETT displacement</strong></em><em> (ETCO2, chest rise/fall, laryngoscopy, auscultate, CXR) </em></td></tr><tr><td><strong>3. </strong></td><td><em><strong>Check for ETT obstruction </strong></em><em>– pass suction catheter, suction secretions </em></td></tr><tr><td><strong>4. </strong></td><td><em><strong>Check for pneumothorax</strong></em><em> with lung USS, decompress if present </em></td></tr><tr><td><strong>5. </strong></td><td><em><strong>Check for dynamic hyperinflation</strong></em><em> – disconnect ETT, assisted expiration  </em></td></tr><tr><td><strong>6. </strong></td><td><em>Check for equipment problems – vent settings, vent malfunction, kinked tubing </em></td></tr><tr><td><strong>7. </strong></td><td><em>Fluid bolus 10-20mg/kg </em></td></tr><tr><td><strong>8. </strong></td><td><em>Elevate head of bed 30 degrees </em></td></tr><tr><td><strong>9. </strong></td><td><em>Pause sedation infusion, switch to ketamine boluses until stable </em></td></tr><tr><td colspan=\"2\"><em>Ensure patient paralysed </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>6-10 breaths per minute </em></td></tr><tr><td><strong>PEEP </strong></td><td><em>Minimal when patient paralysed 0-5cmH</em><em>2</em><em>0 </em></td></tr><tr><td><strong>I:E ratio </strong></td><td><em>Prolonged expiration 1:3 or 1:4 </em></td></tr><tr><td><strong>Peak airway pressure  </strong></td><td><em>40-50cmH</em><em>2</em><em>0  </em></td></tr><tr><td><strong>Plateau pressure </strong></td><td><em>&lt;25cmH</em><em>2</em><em>0 </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><em><strong>Permissive hypercapnia</strong></em><em> – allow elevated PCO</em><em>2</em><em> provided pH &gt; 7.1-7.2 </em></div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\"><em><strong>Keep well sedated and paralysed </strong></em></div><div class=\"answer-line\"><strong>4. </strong></div><div class=\"answer-line\"><em><strong>Optimise medical management of underlying asthma (bronchodilators, steroids) </strong></em></div><div class=\"answer-line\"><em>Monitor waveforms for dynamic hyperinflation (sawtooth pattern) </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 25yo male presents with left wrist pain after falling off his skateboard onto an outstretched hand. His X-rays are presented below:","parts":[{"id":"a","label":"Part A","prompt":"List (2) positive findings and (1) relevant negative finding. (3 marks)\nPositive 1\nPositive 2\nRelevant negative"},{"id":"b","label":"Part B","prompt":"What is the most significant immediate complication of this injury (1 mark) and how would you assess for this? (2 marks) Complication\nAssessment 1\nAssessment 2"},{"id":"c","label":"Part C","prompt":"Outline your immediate management of this patient (4 marks) 1. 2. 3. 4."},{"id":"d","label":"Part D","prompt":"List (2) long-term complications of this injury. (2 marks) 1. 2."}],"propPages":["asset:imga6a4136535a9a06dc3","asset:img9381a1b4196fc6ff27"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 25yo male presents with left wrist pain after falling off his skateboard onto an outstretched</div><div class=\"answer-line\">hand.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Median nerve injury </em></div><div class=\"answer-line\"><strong>Assessment 1 </strong></div><div class=\"answer-line\"><em>Assess for sensory deficit in median nerve distribution (radial 3 ½ </em></div><div class=\"answer-line\"><em>fingers) </em></div><div class=\"answer-line\"><strong>Assessment 2 </strong></div><div class=\"answer-line\"><em>Assess for power of thumb movements: aBduction and opposition</em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>Analgesia – reasonable agents with doses </em></td></tr><tr><td><strong>2. </strong></td><td><em>Urgent orthopaedic consultation</em></td></tr><tr><td><strong>3. </strong></td><td><em><strong>Urgent closed reduction</strong></em><em> under procedural sedation (will still need ORIF) </em></td></tr><tr><td><strong>4. </strong></td><td><em>Immobilisation sugartong splint </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><em>Wrist instability; degenerative arthritis; chronic pain </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"You are the senior medical officer in charge at a tertiary hospital ED. You receive advance notification that an ambulance will be arriving in 15 minutes.\nThe patient is a 27yo male with known schizophrenia who has deliberately severed his own\npenis with a kitchen knife. The patient is highly agitated and has been combative, requiring police presence.\nThere is an estimated 1-2L blood loss at scene, with the ambulance officer describing the\nscene as a “blood bath”.","parts":[{"id":"a","label":"Part A","prompt":"Outline the preparations you would make to receive this patient. (6 marks) 1. 2. 3. 4. 5. 6. The police officer hands you a zip-lock bag containing the amputated penis."},{"id":"b","label":"Part B","prompt":"What would you do with it? (2 marks) 1. 2. One of the ambulance officers has sustained a blood splash to the eye whilst restraining the patient."},{"id":"c","label":"Part C","prompt":"What would you advise them? (4 marks) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>1. </strong><em><strong>Prepare resus bay</strong></em><em>: suture kits, IV cannulas, blood box, check airway equipment </em></div><div class=\"answer-line\"><strong>2. </strong><em><strong>Assign roles</strong></em><em>: Airway, sedation, IV access, haemorrhage control, security for restraint </em></div><div class=\"answer-line\"><strong>3. </strong><em><strong>Urgent surgical notifications</strong></em><em> – trauma surgery, plastics, urology (may be suitable for </em></div><div class=\"answer-line\"><em>replant) </em></div><div class=\"answer-line\"><strong>4. </strong><em><strong>PPE for staff</strong></em><em> – Face shields, gowns, gloves </em></div><div class=\"answer-line\"><strong>5. </strong><em><strong>Prepare sedation</strong></em><em> for behavioural control – e.g. droperidol 10mg + midazolam 10mg </em></div><div class=\"answer-line\"><em>IM/IV </em></div><div class=\"answer-line\"><strong>6. </strong><em><strong>Prepare blood products</strong></em><em> – Call blood bank, activate MTP </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>1. </strong><em>Wash in normal saline and </em><strong> </strong></div><div class=\"answer-line\"><strong>2. </strong><em><strong>Place in bag of saline on ice</strong></em><em> (avoid direct contact with ice) </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em><strong>Rinse the eye thoroughly</strong></em><em> with normal saline </em></td></tr><tr><td><strong>2. </strong></td><td><em>Low risk exposure (&lt;0.01% HIV transmission) but merits medical assessment </em></td></tr><tr><td><strong>3. </strong></td><td><em>Register as patient for </em><em><strong>full blood-borne virus risk assessment</strong></em><strong> </strong></td></tr><tr><td><strong>4. </strong></td><td><em>Will need </em><em><strong>routine bloods</strong></em><em> for HIV, Hep B/C and appropriate follow-up </em></td></tr><tr><td colspan=\"2\"><em>Treating clinician will need to also need to try and obtain consent to test the patient</em></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"You are the consultant working in a mixed Emergency Dept when the triage nurse alerts you\nto the arrival of a 15-month-old boy with lethargy & vomiting.\nThe child was found in the back seat of a car at the local RSL club car park. Outside\ntemperature is 38°C.\nThe child is moved straight into the resuscitation area and monitoring is placed. Vital signs are recorded as follows\n\nTemp (tympanic)\n40.6°C\n\nHR\n170bpm\n\nBP\n60/40\n\nRR\n\nSaO2\n90% on RA AVPU scale P","parts":[{"id":"a","label":"Part A","prompt":"List (2) physiological characteristics of children which make them more susceptible to heat-related illness compared with adults. (2 marks) 1. 2. Intravenous access is obtained and initial resuscitation has commenced."},{"id":"b","label":"Part B","prompt":"Prioritise a list of (4) methods you would use to rapidly cool this child. (4 marks) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"In addition to the above cooling measures, outline (3) further actions in your acute resuscitation plan. (3 marks) 1. 2. 3. As you commence cooling measures, the child starts to have a generalised seizure."},{"id":"d","label":"Part D","prompt":"List (3) possible causes and a specific treatment for each. (3 marks) Cause of seizure Treatment"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Higher basal metabolic rate than adults -&gt; produce more heat </em></div><div class=\"answer-line\"><em>Higher surface area : mass ratio resulting in greater heat absorption in hot </em></div><div class=\"answer-line\"><em>environments </em></div><div class=\"answer-line\"><em>Smaller absolute blood volume resulting in lower blood-bore heat dissipation from core </em></div><div class=\"answer-line\"><em>to surface </em></div><div class=\"answer-line\"><em>Lower rate of sweating than adults / begin sweating at higher temperatures </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>3. </strong><em>Ice packs to neck, groin and axillae (minimise shivering with BZD)</em><em><strong> </strong></em></div><div class=\"answer-line\"><strong>4. </strong><em>Cool IVF 4°C</em><em><strong> </strong></em></div><div class=\"answer-line\"><em>NOT antipyretics, evidence for invasive measures lacking, cold immersion impracticable </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>3. </strong><em>Ensure child on continuous cardiac and core rectal temperature monitoring, IDC </em></div><div class=\"answer-line\"><em>OR </em></div><div class=\"answer-line\"><em>Seek and treat complications eg pulmonary oedema, DIC, AKI </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><em><strong>Hyponatraemia </strong></em></td><td><em><strong>IV bolus 3mL/kg 3% saline (repeat 2x until </strong></em></td></tr><tr><td><em><strong>cessation of seizure </strong></em></td><td></td></tr><tr><td><em>Febrile convulsion </em></td><td><em>IV midazolam 0.15mg/kg </em></td></tr><tr><td><em>Supportive, ongoing cooling </em></td><td></td></tr><tr><td><em>Cerebral oedema </em></td><td><em>IV midazolam 0.15mg/kg </em></td></tr><tr><td><em>Nurse 30° head up </em></td><td></td></tr><tr><td><em>Pre-existing seizure disorder </em></td><td><em>IV midazolam 0.15mg/kg </em></td></tr><tr><td><em>IV phenytoin/leviteracitam </em></td><td></td></tr><tr><td><em>Cerebral haemorrhage 2° to DIC </em></td><td><em> Supportive, neuroSx referral </em></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 45yo female presents with headaches and expressive dysphasia. Past medical history is\nunknown. She has a background of homelessness, alcohol abuse and IVDU. Her contrast-enhanced CT brain is shown below :","parts":[{"id":"a","label":"Part A","prompt":"What is the main finding the CT scan? (1 mark)"},{"id":"b","label":"Part B","prompt":"List (4) differential diagnoses for this lesion. (4 marks) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"List (6) specific things you would assess for on clinical exam. (6 marks) 1. 2. 3. 4. 5. 6."}],"propPages":["asset:img95bf031114bdb4b3b0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Large </em><em><strong>ring-enhancing lesion</strong></em><em> in left frontal lobe with minimal MLS </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Infarct (subacute) </em></div><div class=\"answer-line\"><em>Contusion </em></div><div class=\"answer-line\"><em>Demyelination </em></div><div class=\"answer-line\"><em>Radiation necrosis / resolving haematoma </em></div><div class=\"answer-line\"><em>Lymphoma </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>1. </strong><em>Full set of vital signs: monitor pain scores, fever, GCS </em></div><div class=\"answer-line\"><strong>2. </strong><em>Full neuro exam to check for deficits, signs of raised ICP (papilloedema) </em></div><div class=\"answer-line\"><strong>3. </strong><em><strong>Breast exam</strong></em><em> for lumps (?breast primary) </em></div><div class=\"answer-line\"><strong>4. </strong><em>Examine for </em><em><strong>soft tissue infections</strong></em><em> or </em><em><strong>track marks</strong></em><em> (?abscess) </em></div><div class=\"answer-line\"><strong>5. </strong><em>Check for signs of endocarditis: murmurs, peripheral stigmata </em></div><div class=\"answer-line\"><strong>6. </strong><em>Assess for alcohol withdrawal / commence AWS  </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"An 11-year-old boy is brought into the Emergency Department with a 3-week history of\nworsening groin pain and limp. He presents today as he has been unable to weight bear. An X-ray is performed :","parts":[{"id":"a","label":"Part A","prompt":"What is the diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"List four (4) other causes of atraumatic limp in this age group (4 marks) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"What is considered the most reliable examination finding for this condition? (1 mark)"},{"id":"d","label":"Part D","prompt":"List three (3) priorities of management. (3 marks) 1. 2. 3."},{"id":"e","label":"Part E","prompt":"What are three (3) potential complications associated with this condition? (3 marks) 1. 2. 3."}],"propPages":["asset:img4d77226ae75fe0b09e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Left slipped capital/upper femoral epiphysis </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Infection : septic arthritis/OM/discitis/cellulitis </em></div><div class=\"answer-line\"><em>Tumour </em></div><div class=\"answer-line\"><em>Regional lymphadenitis </em></div><div class=\"answer-line\"><em>Serum sickness </em></div><div class=\"answer-line\"><em>Overuse syndrome </em></div><div class=\"answer-line\"><em>Osteochondritis dessicans </em></div><div class=\"answer-line\"><em>Chondromalacia </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Obligatory external rotation of the leg during hip flexion </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><em>Analgesia </em></div><div class=\"answer-line\"><em>Keep non-weight bearing </em></div><div class=\"answer-line\"><em>Admit under ortho for surgical stabilisation </em></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><em>Osteonecrosis </em></div><div class=\"answer-line\"><em>Chondrolysis </em></div><div class=\"answer-line\"><em>OA </em></div><div class=\"answer-line\"><em>Impingement </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 45yo female who presented to your ED with sore throat and fever. She has no past medical history but is a current smoker.","parts":[{"id":"a","label":"Part A","prompt":"Give (6) features on examination that would flag a more sinister pathology. (6 marks) 1. 2. 3. 4. 5. 6. A CT scan of the patient is performed and a slice is shown below :"},{"id":"b","label":"Part B","prompt":"List (6) most relevant findings on the above image. (6 marks) 1. 2. 3. 4. 5. 6."},{"id":"c","label":"Part C","prompt":"Outline your immediate management priorities (6 marks) 1. 2. 3. 4. 5. 6."}],"propPages":["asset:img2df7700aa6954c852b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Inability to swallow saliva </em></div><div class=\"answer-line\"><em>Tripod positioning/inability to lie flat </em></div><div class=\"answer-line\"><em>Vital signs (evidence of hypoxia/shock) </em></div><div class=\"answer-line\"><em>Poor dentition </em></div><div class=\"answer-line\"><em>Elevated floor of mouth </em></div><div class=\"answer-line\"><em>Trismus </em></div><div class=\"answer-line\"><em>Stridor </em></div><div class=\"answer-line\"><em>Altered voice </em></div><div class=\"answer-line\"><em>Dyspnoea/increased WOB </em></div><div class=\"answer-line\"><em>Erythema/swelling of neck or submandibular region </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Airway deviation to R </em></div><div class=\"answer-line\"><em>Enhancing, loculated, fluid density collection in L prevertebral space </em></div><div class=\"answer-line\"><em>Overlying soft tissue swelling/stranding/inflammation </em></div><div class=\"answer-line\"><em>Significant lymphadenopathy  </em></div><div class=\"answer-line\"><em>Patent airway at level of hyoid </em></div><div class=\"answer-line\"><em>Absence of free gas </em></div><div class=\"answer-line\"><em>No identified FB </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Expedient airway management : preferably awake fibre optic intubation in OT, </em></div><div class=\"answer-line\"><em>performed by anaesthetics.  </em></div><div class=\"answer-line\"><em>Reduce airway swelling : dexamethasone 8mg IV, nebulised adrenaline 5ml 1:1000 </em></div><div class=\"answer-line\"><em>Equipment arranged for emergent airway management in ED incl FONA </em></div><div class=\"answer-line\"><em>Broad spectrum empiric antibiotics (Augmentin 1.2g IV q6hourly) </em></div><div class=\"answer-line\"><em>Urgent ENT referral for I&amp;D </em></div><div class=\"answer-line\"><em>Supportive : analgesia, NBM/IVF </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
